-- Local reconstruction prerequisite: this production role predates checked-in migrations.
-- No users are seeded or assigned; this file is never a production migration.
insert into public.roles(code,name) values('ENCARGADA_LABORATORIO','Encargada de Laboratorio') on conflict(code) do nothing;
insert into public.role_permissions(role_id,permission_code) select r.id,p.permission_code from public.roles r cross join public.app_permissions p where r.code='ENCARGADA_LABORATORIO' and p.permission_code in ('ACTIONS_VIEW','ACTIONS_WRITE','ANALYTICAL_QC_VIEW','ANALYTICAL_QC_WRITE','BLOOD_INVENTORY_VIEW','BLOOD_INVENTORY_WRITE','COLD_CHAIN_VIEW','COLD_CHAIN_WRITE','COMPETENCY_VIEW','DAILY_REPORT_CLOSE','DAILY_REPORT_SUBMIT','DAILY_REPORT_VIEW','DAILY_REPORT_WRITE','DASHBOARD_VIEW','DOCUMENTS_VIEW','DONOR_AGENDA_CONFIG','DONOR_OUTREACH_VIEW','DONOR_OUTREACH_WRITE','DONORS_VIEW','DONORS_WRITE','HEMOVIGILANCE_VIEW','HEMOVIGILANCE_WRITE','ORDER_PLAN_VIEW','ORDER_PLAN_WRITE','PURCHASE_RECEIVE','PURCHASE_VIEW','QUALITY_VIEW','RESOURCES_VIEW','RESOURCES_WRITE','SCREENING_VIEW','SCREENING_WRITE','SUPPLIERS_VIEW','SUPPLY_VIEW','TRAINING_SELF','UNIT_RELEASE','VALUE_CHAIN_VIEW','VALUE_CHAIN_WRITE','WORKFLOW_VIEW') on conflict do nothing;
